export function buildStatusStrip({completed,total,phase='understanding',detail=''}={}){const t=Number(total),c=Number(completed);const measured=Number.isFinite(t)&&t>0&&Number.isFinite(c)&&c>=0;return Object.freeze({kind:measured?'measured':'phase',phase:String(phase),completed:measured?Math.min(c,t):null,total:measured?t:null,percent:measured?Math.round(Math.min(c,t)/t*100):null,detail:String(detail)})}
